-- Perbaikan nama kecamatan (seharusnya Pinang, bukan Sudimara Pinang).
update public.docs set data=data||'{"kecamatan":"Pinang"}'::jsonb where coll='pengaturan' and id='rt';

-- Contoh pengumuman dengan poster (aman; dapat dihapus lewat Area Pengurus).
insert into public.docs(coll,id,data) values ('kegiatan','pg-contoh-kerjabakti','{"judul": "Kerja bakti lingkungan RT 09", "ringkasan": "Minggu, 22 November 2026 pukul 07.00 WIB. Kumpul di depan Pos Ronda, Hidup Baru I. Mohon membawa sapu, cangkul, atau kantong sampah.", "tanggal": "2026-11-16", "tipe": "pengumuman", "asal": "RT 09", "sumber": "Contoh", "poster": "data:image/jpeg;base64,", "sampel": true}') on conflict (coll,id) do update set data=excluded.data;
insert into public.docs(coll,id,data) values ('kegiatan','pg-contoh-pertemuan','{"judul": "Pertemuan warga Desember 2026", "ringkasan": "Sabtu, 12 Desember 2026 pukul 20.00 WIB di rumah D. Suparjo Murcono (Hidup Baru IA / 25). Agenda: laporan kas, iuran 2027, dan keamanan lingkungan.", "tanggal": "2026-11-15", "tipe": "pengumuman", "asal": "RT 09", "sumber": "Contoh", "poster": "data:image/jpeg;base64,", "sampel": true}') on conflict (coll,id) do update set data=excluded.data;
insert into public.docs(coll,id,data) values ('kegiatan','pg-contoh-posyandu','{"judul": "Posyandu dan pemeriksaan kesehatan gratis", "ringkasan": "Kamis, 3 Desember 2026 pukul 09.00 WIB di Balai Warga RW 01. Penimbangan balita, imunisasi, dan cek tekanan darah untuk lansia.", "tanggal": "2026-11-14", "tipe": "pengumuman", "asal": "Kelurahan", "sumber": "Contoh", "poster": "data:image/jpeg;base64,", "sampel": true}') on conflict (coll,id) do update set data=excluded.data;
